mapper.select:
SELECT k.id AS knowledgeId, k.title AS title, k.summary AS summary, k.type AS type, k.cover_url AS coverUrl, k.view_count AS viewCount, f.created_at AS favoriteAt FROM favorite_record f INNER JOIN kb_knowledge k ON k.id = f.knowledge_id WHERE f.user_id = #{userId} AND k.status = 1 AND k.is_deleted = 0
AND (k.title LIKE CONCAT('%', #{keyword}, '%') OR k.summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY f.created_at DESC, f.id DESC LIMIT #{offset}, #{pageSize}
